<?php require 'config.php';require 'includes/functions.php';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['product_id']??0);$_SESSION['wishlist']??=[];if(in_array($id,$_SESSION['wishlist']))$_SESSION['wishlist']=array_values(array_diff($_SESSION['wishlist'],[$id]));else $_SESSION['wishlist'][]=$id;flash('Wishlist updated.');go('wishlist.php');}$ids=array_map('intval',$_SESSION['wishlist']??[]);$items=[];if($ids){$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);$items=$s->fetchAll();}$title='Wishlist';require 'includes/header.php';?><div class="page-head"><span class="eyebrow">SAVED FOR LATER</span><h1>Your wishlist</h1></div><div class="product-grid"><?php foreach($items as $p):?><article class="product-card"><a class="product-image" href="product.php?id=<?=$p['id']?>"><img src="<?=e($p['image_url'])?>" alt=""></a><div class="product-info"><h3><?=e($p['name'])?></h3><b><?=money($p['price'])?></b><form method="post"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="link">Remove from wishlist</button></form></div></article><?php endforeach;?></div><?php if(!$items):?><div class="empty">No saved pieces yet. <a href="index.php">Explore the collection</a>.</div><?php endif;?><?php require 'includes/footer.php';?>